#include <cstdlib>
#include <openssl/dsa.h>
#include <openssl/pem.h>
#include <string>

std::string create_dsa_key() {
    char param_filename[] = "/tmp/tempXXXXXX";
    int fd = mkstemp(param_filename);
    if (fd == -1) {
        return "";
    }

    // Generate DSA parameters
    FILE* param_file = fopen(param_filename, "w");
    if (!param_file) {
        close(fd);
        return "";
    }

    DSA* dsa = NULL;
    dsa = DSA_new();
    if (!dsa) {
        fclose(param_file);
        close(fd);
        return "";
    }

    dsa = DSAGenerateKey(2048);
    if (!dsa) {
        fclose(param_file);
        close(fd);
        return "";
    }

    FILE* key_file = fopen(param_filename, "w");
    if (!key_file) {
        DSA_free(dsa);
        fclose(param_file);
        close(fd);
        return "";
    }

    PEM_write_DSA(key_file, dsa);
    fclose(key_file);
    DSA_free(dsa);
    fclose(param_file);
    close(fd);

    // Read the generated key from the file
    FILE* read_key_file = fopen(param_filename, "r");
    if (!read_key_file) {
        return "";
    }

    char buffer[1024];
    std::string result;
    while (fgets(buffer, sizeof(buffer), read_key_file)) {
        result += buffer;
    }
    fclose(read_key_file);

    // Remove the temporary file
    unlink(param_filename);

    return result;
}
